Script:
param([string]$SubmissionPath)
$ErrorActionPreference='Stop'
Set-Location -LiteralPath 'F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$source='c0effa290eee225c296f779a85b9d79109d789a5'
$control='artifacts/relations-measurements/final-packages-r45'
while(!(Test-Path -LiteralPath $SubmissionPath)){Start-Sleep -Milliseconds 20}
$queue=Get-Content -LiteralPath $SubmissionPath -Raw|ConvertFrom-Json
$steps=[Collections.Generic.List[object]]::new()
function Run-Step([string]$Name,[string]$File,[string[]]$Arguments){
 $stdout=[IO.Path]::GetFullPath("$control/$Name.stdout.log")
 $stderr=[IO.Path]::GetFullPath("$control/$Name.stderr.log")
 $started=[DateTime]::UtcNow
 & pwsh -NoProfile -File $File @Arguments 1>$stdout 2>$stderr
 $code=$LASTEXITCODE
 $step=[pscustomobject]@{Name=$Name;QueueId=$queue.Id;SourceCommit=$source;Executable='pwsh';Arguments=@('-NoProfile','-File',$File)+$Arguments;StartedAtUtc=$started;FinishedAtUtc=[DateTime]::UtcNow;ExitCode=$code;Stdout=$stdout;Stderr=$stderr}
 $steps.Add($step)
 $steps|ConvertTo-Json -Depth 7|Set-Content -LiteralPath "$control/evidence-stages.json" -Encoding utf8
 Write-Output ('EVIDENCE_STAGE '+($step|ConvertTo-Json -Depth 7 -Compress))
 Get-Content -LiteralPath $stdout -Tail 10|Write-Output
 if($code -ne 0){Get-Content -LiteralPath $stderr -Tail 20|Write-Output;exit $code}
}
try{
 Run-Step 'ArchiveMeasurements' ([IO.Path]::GetFullPath('artifacts/relations-measurements/focused-native-r45/archive.ps1')) @()
 Run-Step 'ReadPackageCodegen' ([IO.Path]::GetFullPath('docs/evidence/ECS-Relations-2026-10-19/final-packages-r45/Read-Package-Codegen.ps1')) @('-ReaderQueueId',[string]$queue.Id)
}finally{Remove-Item -LiteralPath $PSCommandPath}
